def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split pre-release (everything after '-')
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(int(x) for x in version_part.split('.'))

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
            prerelease_tuples = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    prerelease_tuples.append((0, int(identifier)))
                else:
                    prerelease_tuples.append((1, identifier))
            prerelease = tuple(prerelease_tuples)
        else:
            prerelease = None

        return version_nums, prerelease

    def sort_key(v):
        version_nums, prerelease = parse_version(v)

        # For sorting: if there's a prerelease, it comes before no prerelease
        # So we use a tuple where: (version_nums, has_prerelease_flag, prerelease_data)
        if prerelease is None:
            return (version_nums, 1, ())
        else:
            return (version_nums, 0, prerelease)

    # Stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

